use clap::{Parser, ValueEnum};
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use std::error::Error;
use std::io;
use tui::{
    backend::{Backend, CrosstermBackend},
    widgets::{Block, Borders, Paragraph},
    layout::{Constraint, Direction, Layout},
    style::{Color, Modifier, Style},
    text::{Span, Spans},
    Terminal,
};
use std::time::Instant;
use rand::seq::SliceRandom;
use std::fs;
use chrono::Local;
use std::path::PathBuf;

mod word_lists;
use word_lists::{ENGLISH_WORDS, ENGLISH1K_WORDS, ENGLISH10K_WORDS};

#[derive(Parser, Debug)]
#[command(name = "thokr")]
#[command(version = "0.4.1")]
#[command(about = "sleek typing tui with visualized results and historical logging")]
struct Args {
    #[arg(
        short,
        long,
        value_name = "NUMBER_OF_WORDS",
        default_value = "15",
        help = "number of words to use in test"
    )]
    number_of_words: Option<usize>,

    #[arg(
        short = 'l',
        long,
        value_name = "SUPPORTED_LANGUAGE",
        default_value = "english",
        help = "language to pull words from",
        value_parser = ["english", "english1k", "english10k"]
    )]
    supported_language: String,

    #[arg(
        short = 'p',
        long,
        value_name = "PROMPT",
        help = "custom prompt to use"
    )]
    prompt: Option<String>,

    #[arg(
        short = 's',
        long,
        value_name = "NUMBER_OF_SECS",
        help = "number of seconds to run test"
    )]
    number_of_secs: Option<u64>,

    #[arg(
        short = 'f',
        long,
        value_name = "NUMBER_OF_SENTENCES",
        help = "number of sentences to use in test"
    )]
    full_sentences: Option<usize>,
}

struct TypingTest {
    prompt: Vec<String>,
    user_input: String,
    input_index: usize,
    start_time: Option<Instant>,
    end_time: Option<Instant>,
    time_limit: Option<u64>,
}

impl TypingTest {
    fn new(prompt: Vec<String>, time_limit: Option<u64>) -> Self {
        TypingTest {
            prompt,
            user_input: String::new(),
            input_index: 0,
            start_time: None,
            end_time: None,
            time_limit,
        }
    }

    fn start_if_needed(&mut self) {
        if self.start_time.is_none() {
            self.start_time = Some(Instant::now());
        }
    }

    fn is_time_exceeded(&self) -> bool {
        if let (Some(start), Some(limit)) = (self.start_time, self.time_limit) {
            start.elapsed().as_secs() >= limit
        } else {
            false
        }
    }

    fn add_character(&mut self, c: char) {
        self.start_if_needed();
        if self.is_time_exceeded() {
            return;
        }

        let target = self.prompt.join(" ");
        if self.input_index < target.len() {
            self.user_input.push(c);
            self.input_index += 1;
        }
    }

    fn remove_character(&mut self) {
        if self.input_index > 0 {
            self.user_input.pop();
            self.input_index -= 1;
        }
    }

    fn is_complete(&self) -> bool {
        let target = self.prompt.join(" ");
        self.user_input == target
    }

    fn get_accuracy(&self) -> f64 {
        let target = self.prompt.join(" ");
        let mut correct = 0;
        for (a, b) in self.user_input.chars().zip(target.chars()) {
            if a == b {
                correct += 1;
            }
        }
        if target.len() == 0 {
            100.0
        } else {
            (correct as f64 / target.len() as f64) * 100.0
        }
    }

    fn get_wpm(&self) -> f64 {
        if let Some(start) = self.start_time {
            if let Some(end) = self.end_time {
                let duration_secs = (end - start).as_secs_f64();
                let word_count = self.user_input.split_whitespace().count() as f64;
                (word_count / duration_secs) * 60.0
            } else {
                0.0
            }
        } else {
            0.0
        }
    }
}

fn get_word_list(language: &str) -> &'static [&'static str] {
    match language {
        "english1k" => ENGLISH1K_WORDS,
        "english10k" => ENGLISH10K_WORDS,
        _ => ENGLISH_WORDS,
    }
}

fn generate_prompt(args: &Args) -> Vec<String> {
    if let Some(custom) = &args.prompt {
        custom.split_whitespace().map(|s| s.to_string()).collect()
    } else if let Some(sentences) = args.full_sentences {
        generate_sentences(sentences)
    } else {
        let word_count = args.number_of_words.unwrap_or(15);
        let word_list = get_word_list(&args.supported_language);
        let mut rng = rand::thread_rng();

        word_list
            .choose_multiple(&mut rng, word_count)
            .map(|&s| s.to_string())
            .collect()
    }
}

fn generate_sentences(count: usize) -> Vec<String> {
    let words = ENGLISH_WORDS;
    let mut rng = rand::thread_rng();
    let mut result = Vec::new();

    for _ in 0..count {
        let sentence_length = 5 + (rng.random::<usize>() % 6);
        let mut sentence_words: Vec<String> = words
            .choose_multiple(&mut rng, sentence_length)
            .map(|&s| s.to_string())
            .collect();

        if let Some(first) = sentence_words.first_mut() {
            *first = first.chars().next().map(|c| c.to_uppercase().collect::<String>()).unwrap_or_default() + &first[1..];
        }

        let sentence = format!("{}.", sentence_words.join(" "));
        result.push(sentence);
    }

    result
}

fn setup_terminal() -> Result<Terminal<CrosstermBackend<io::Stdout>>, Box<dyn Error>> {
    let stdout = io::stdout();
    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok(terminal)
}

fn restore_terminal(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
) -> Result<(), Box<dyn Error>> {
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
    )?;
    terminal.show_cursor()?;
    Ok(())
}

fn run_typing_test(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    mut test: TypingTest,
) -> Result<(), Box<dyn Error>> {
    enable_raw_mode()?;
    execute!(io::stdout(), EnterAlternateScreen)?;
    terminal.hide_cursor()?;

    loop {
        let target = test.prompt.join(" ");

        if test.is_time_exceeded() {
            test.end_time = Some(Instant::now());
            break;
        }

        terminal.draw(|f| {
            draw_typing_ui(f, &test, &target);
        })?;

        if crossterm::event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char(c) => {
                        test.add_character(c);
                        if test.is_complete() {
                            test.end_time = Some(Instant::now());
                            break;
                        }
                    }
                    KeyCode::Backspace => test.remove_character(),
                    KeyCode::Left => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Right => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Esc => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    _ => {}
                }
            }
        }
    }

    terminal.draw(|f| {
        let target = test.prompt.join(" ");
        draw_results_ui(f, &test, &target);
    })?;

    // Show results for a moment
    std::thread::sleep(std::time::Duration::from_secs(2));

    restore_terminal(terminal)?;

    // Log results
    log_results(&test)?;

    Ok(())
}

fn draw_typing_ui<B: Backend>(f: &mut tui::Frame<B>, test: &TypingTest, target: &str) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(20),
            Constraint::Percentage(40),
            Constraint::Percentage(40),
        ])
        .split(f.size());

    // Display prompt
    let prompt_text = vec![Spans::from(Span::styled(
        target,
        Style::default().fg(Color::White),
    ))];
    let prompt = Paragraph::new(prompt_text)
        .block(Block::default().borders(Borders::ALL).title("Prompt"))
        .style(Style::default().fg(Color::White));
    f.render_widget(prompt, chunks[1]);

    // Display user input with colors
    let mut input_spans = Vec::new();
    for (i, c) in target.chars().enumerate() {
        let user_char = test.user_input.chars().nth(i);
        if let Some(uc) = user_char {
            if uc == c {
                input_spans.push(Span::styled(
                    uc.to_string(),
                    Style::default().fg(Color::Green),
                ));
            } else {
                input_spans.push(Span::styled(
                    uc.to_string(),
                    Style::default().fg(Color::Red),
                ));
            }
        }
    }

    // Show remaining characters to type
    if test.user_input.len() < target.len() {
        input_spans.push(Span::styled(
            target[test.user_input.len()..].to_string(),
            Style::default().fg(Color::DarkGray),
        ));
    }

    let input_text = vec![Spans::from(input_spans)];
    let input = Paragraph::new(input_text)
        .block(Block::default().borders(Borders::ALL).title("Input"))
        .style(Style::default().fg(Color::White));
    f.render_widget(input, chunks[2]);

    // Display timer/info
    let elapsed = if let Some(start) = test.start_time {
        format!("Elapsed: {:.1}s", start.elapsed().as_secs_f64())
    } else {
        "Not started".to_string()
    };

    let info_text = vec![Spans::from(Span::raw(elapsed))];
    let info = Paragraph::new(info_text)
        .block(Block::default().borders(Borders::ALL).title("Info"))
        .style(Style::default().fg(Color::Cyan));
    f.render_widget(info, chunks[0]);
}

fn draw_results_ui<B: Backend>(f: &mut tui::Frame<B>, test: &TypingTest, target: &str) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(f.size());

    let wpm = test.get_wpm();
    let accuracy = test.get_accuracy();
    let elapsed = if let (Some(start), Some(end)) = (test.start_time, test.end_time) {
        (end - start).as_secs_f64()
    } else {
        0.0
    };

    let wpm_text = format!("WPM: {:.2}", wpm);
    let accuracy_text = format!("Accuracy: {:.2}%", accuracy);
    let time_text = format!("Time: {:.2}s", elapsed);
    let complete_text = if test.is_complete() {
        "✓ Complete"
    } else {
        "✗ Incomplete"
    };

    let wpm_widget = Paragraph::new(wpm_text)
        .block(Block::default().borders(Borders::ALL).title("WPM"))
        .style(Style::default().fg(Color::Green));
    f.render_widget(wpm_widget, chunks[0]);

    let accuracy_widget = Paragraph::new(accuracy_text)
        .block(Block::default().borders(Borders::ALL).title("Accuracy"))
        .style(Style::default().fg(Color::Blue));
    f.render_widget(accuracy_widget, chunks[1]);

    let time_widget = Paragraph::new(time_text)
        .block(Block::default().borders(Borders::ALL).title("Time"))
        .style(Style::default().fg(Color::Cyan));
    f.render_widget(time_widget, chunks[2]);

    let complete_widget = Paragraph::new(complete_text)
        .block(Block::default().borders(Borders::ALL).title("Status"))
        .style(Style::default().fg(if test.is_complete() { Color::Green } else { Color::Red }));
    f.render_widget(complete_widget, chunks[3]);
}

fn get_config_dir() -> PathBuf {
    if let Ok(xdg_config) = std::env::var("XDG_CONFIG_HOME") {
        PathBuf::from(xdg_config).join("thokr")
    } else if let Some(home) = dirs::home_dir() {
        home.join(".config").join("thokr")
    } else {
        PathBuf::from(".config/thokr")
    }
}

fn log_results(test: &TypingTest) -> Result<(), Box<dyn Error>> {
    let config_dir = get_config_dir();
    fs::create_dir_all(&config_dir)?;

    let log_file = config_dir.join("log.csv");
    let wpm = test.get_wpm();
    let accuracy = test.get_accuracy();
    let elapsed = if let (Some(start), Some(end)) = (test.start_time, test.end_time) {
        (end - start).as_secs_f64()
    } else {
        0.0
    };

    let timestamp = Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    let log_entry = format!(
        "{},{:.2},{:.2},{:.2}\n",
        timestamp, wpm, accuracy, elapsed
    );

    // Append to log file
    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_file)?;
    file.write_all(log_entry.as_bytes())?;

    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    // Check if stdin is a TTY
    if !atty::is(atty::Stream::Stdin) {
        eprintln!("error: stdin must be a tty\n");
        eprintln!("USAGE:");
        eprintln!("    thokr [OPTIONS]\n");
        eprintln!("For more information try --help");
        std::process::exit(1);
    }

    let args = Args::parse();
    let prompt = generate_prompt(&args);
    let test = TypingTest::new(prompt, args.number_of_secs);

    let mut terminal = setup_terminal()?;
    run_typing_test(&mut terminal, test)?;

    Ok(())
}
