fn setup_terminal() -> Result<Terminal<CrosstermBackend<io::Stdout>>, Box<dyn Error>> {
    let stdout = io::stdout();
    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok(terminal)
}

fn restore_terminal(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
) -> Result<(), Box<dyn Error>> {
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
    )?;
    terminal.show_cursor()?;
    Ok(())
}

fn run_typing_test(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    mut test: TypingTest,
) -> Result<(), Box<dyn Error>> {
    enable_raw_mode()?;
    execute!(io::stdout(), EnterAlternateScreen)?;
    terminal.hide_cursor()?;

    loop {
        let target = test.prompt.join(" ");

        if test.is_time_exceeded() {
            test.end_time = Some(Instant::now());
            break;
        }

        terminal.draw(|f| {
            draw_typing_ui(f, &test, &target);
        })?;

        if crossterm::event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char(c) => {
                        test.add_character(c);
                        if test.is_complete() {
                            test.end_time = Some(Instant::now());
                            break;
                        }
                    }
                    KeyCode::Backspace => test.remove_character(),
                    KeyCode::Left => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Right => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Esc => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    _ => {}
                }
            }
        }
    }

    terminal.draw(|f| {
        let target = test.prompt.join(" ");
        draw_results_ui(f, &test, &target);
    })?;

    // Show results for a moment
    std::thread::sleep(std::time::Duration::from_secs(2));

    restore_terminal(terminal)?;

    // Log results
    log_results(&test)?;

    Ok(())
}

