        let target = self.prompt.join(" ");
        if self.input_index < target.len() {
            self.user_input.push(c);
            self.input_index += 1;
        }
    }

    fn remove_character(&mut self) {
        if self.input_index > 0 {
            self.user_input.pop();
            self.input_index -= 1;
        }
    }

