        let target = self.prompt.join(" ");
        let mut correct = 0;
        for (a, b) in self.user_input.chars().zip(target.chars()) {
            if a == b {
                correct += 1;
            }
        }
        if target.len() == 0 {
            100.0
        } else {
            (correct as f64 / target.len() as f64) * 100.0
        }
    }

    fn get_wpm(&self) -> f64 {
        if let Some(start) = self.start_time {
            if let Some(end) = self.end_time {
                let duration_secs = (end - start).as_secs_f64();
                let word_count = self.user_input.split_whitespace().count() as f64;
