struct TypingTest {
    prompt: Vec<String>,
    user_input: String,
    input_index: usize,
    start_time: Option<Instant>,
    end_time: Option<Instant>,
    time_limit: Option<u64>,
}

impl TypingTest {
    fn new(prompt: Vec<String>, time_limit: Option<u64>) -> Self {
        TypingTest {
            prompt,
            user_input: String::new(),
            input_index: 0,
            start_time: None,
            end_time: None,
            time_limit,
        }
    }

    fn start_if_needed(&mut self) {
        if self.start_time.is_none() {
            self.start_time = Some(Instant::now());
        }
    }

    fn is_time_exceeded(&self) -> bool {
        if let (Some(start), Some(limit)) = (self.start_time, self.time_limit) {
            start.elapsed().as_secs() >= limit
        } else {
            false
        }
    }

    fn add_character(&mut self, c: char) {
        self.start_if_needed();
        if self.is_time_exceeded() {
            return;
        }

        let target = self.prompt.join(" ");
        if self.input_index < target.len() {
            self.user_input.push(c);
            self.input_index += 1;
        }
    }

    fn remove_character(&mut self) {
        if self.input_index > 0 {
            self.user_input.pop();
            self.input_index -= 1;
        }
    }

    fn is_complete(&self) -> bool {
        let target = self.prompt.join(" ");
        self.user_input == target
    }

    fn get_accuracy(&self) -> f64 {
        let target = self.prompt.join(" ");
        let mut correct = 0;
        for (a, b) in self.user_input.chars().zip(target.chars()) {
            if a == b {
                correct += 1;
            }
        }
        if target.len() == 0 {
            100.0
        } else {
            (correct as f64 / target.len() as f64) * 100.0
        }
    }

    fn get_wpm(&self) -> f64 {
        if let Some(start) = self.start_time {
            if let Some(end) = self.end_time {
                let duration_secs = (end - start).as_secs_f64();
                let word_count = self.user_input.split_whitespace().count() as f64;
                (word_count / duration_secs) * 60.0
            } else {
                0.0
            }
        } else {
            0.0
        }
    }
}

fn get_word_list(language: &str) -> &'static [&'static str] {
    match language {
        "english1k" => ENGLISH1K_WORDS,
        "english10k" => ENGLISH10K_WORDS,
        _ => ENGLISH_WORDS,
    }
}

fn generate_prompt(args: &Args) -> Vec<String> {
    if let Some(custom) = &args.prompt {
        custom.split_whitespace().map(|s| s.to_string()).collect()
    } else if let Some(sentences) = args.full_sentences {
        generate_sentences(sentences)
    } else {
        let word_count = args.number_of_words.unwrap_or(15);
        let word_list = get_word_list(&args.supported_language);
        let mut rng = rand::thread_rng();

        word_list
            .choose_multiple(&mut rng, word_count)
            .map(|&s| s.to_string())
            .collect()
    }
}

fn generate_sentences(count: usize) -> Vec<String> {
    let words = ENGLISH_WORDS;
    let mut rng = rand::thread_rng();
    let mut result = Vec::new();

    for _ in 0..count {
        let sentence_length = 5 + (rng.random::<usize>() % 6);
        let mut sentence_words: Vec<String> = words
            .choose_multiple(&mut rng, sentence_length)
            .map(|&s| s.to_string())
            .collect();

        if let Some(first) = sentence_words.first_mut() {
            *first = first.chars().next().map(|c| c.to_uppercase().collect::<String>()).unwrap_or_default() + &first[1..];
        }

        let sentence = format!("{}.", sentence_words.join(" "));
        result.push(sentence);
    }

    result
