fn restore_terminal(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
) -> Result<(), Box<dyn Error>> {
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
    )?;
    terminal.show_cursor()?;
    Ok(())
}

fn run_typing_test(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    mut test: TypingTest,
) -> Result<(), Box<dyn Error>> {
    enable_raw_mode()?;
    execute!(io::stdout(), EnterAlternateScreen)?;
    terminal.hide_cursor()?;

    loop {
        let target = test.prompt.join(" ");

        if test.is_time_exceeded() {
            test.end_time = Some(Instant::now());
            break;
        }

        terminal.draw(|f| {
            draw_typing_ui(f, &test, &target);
        })?;

        if crossterm::event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char(c) => {
                        test.add_character(c);
                        if test.is_complete() {
                            test.end_time = Some(Instant::now());
                            break;
                        }
                    }
                    KeyCode::Backspace => test.remove_character(),
                    KeyCode::Left => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Right => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    KeyCode::Esc => {
                        restore_terminal(terminal)?;
                        return Ok(());
                    }
                    _ => {}
                }
            }
        }
    }

    terminal.draw(|f| {
        let target = test.prompt.join(" ");
        draw_results_ui(f, &test, &target);
    })?;

    // Show results for a moment
    std::thread::sleep(std::time::Duration::from_secs(2));

    restore_terminal(terminal)?;

    // Log results
    log_results(&test)?;

    Ok(())
}

fn draw_typing_ui<B: Backend>(f: &mut tui::Frame<B>, test: &TypingTest, target: &str) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(20),
            Constraint::Percentage(40),
            Constraint::Percentage(40),
        ])
        .split(f.size());

    // Display prompt
    let prompt_text = vec![Spans::from(Span::styled(
        target,
        Style::default().fg(Color::White),
    ))];
    let prompt = Paragraph::new(prompt_text)
        .block(Block::default().borders(Borders::ALL).title("Prompt"))
        .style(Style::default().fg(Color::White));
    f.render_widget(prompt, chunks[1]);

    // Display user input with colors
    let mut input_spans = Vec::new();
    for (i, c) in target.chars().enumerate() {
        let user_char = test.user_input.chars().nth(i);
        if let Some(uc) = user_char {
            if uc == c {
                input_spans.push(Span::styled(
                    uc.to_string(),
                    Style::default().fg(Color::Green),
                ));
            } else {
                input_spans.push(Span::styled(
                    uc.to_string(),
                    Style::default().fg(Color::Red),
                ));
            }
        }
    }

    // Show remaining characters to type
    if test.user_input.len() < target.len() {
        input_spans.push(Span::styled(
            target[test.user_input.len()..].to_string(),
            Style::default().fg(Color::DarkGray),
        ));
    }

    let input_text = vec![Spans::from(input_spans)];
    let input = Paragraph::new(input_text)
        .block(Block::default().borders(Borders::ALL).title("Input"))
        .style(Style::default().fg(Color::White));
    f.render_widget(input, chunks[2]);

    // Display timer/info
    let elapsed = if let Some(start) = test.start_time {
        format!("Elapsed: {:.1}s", start.elapsed().as_secs_f64())
    } else {
        "Not started".to_string()
    };

    let info_text = vec![Spans::from(Span::raw(elapsed))];
    let info = Paragraph::new(info_text)
        .block(Block::default().borders(Borders::ALL).title("Info"))
        .style(Style::default().fg(Color::Cyan));
    f.render_widget(info, chunks[0]);
}

