            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(f.size());

    let wpm = test.get_wpm();
    let accuracy = test.get_accuracy();
    let elapsed = if let (Some(start), Some(end)) = (test.start_time, test.end_time) {
        (end - start).as_secs_f64()
    } else {
        0.0
    };

    let wpm_text = format!("WPM: {:.2}", wpm);
    let accuracy_text = format!("Accuracy: {:.2}%", accuracy);
    let time_text = format!("Time: {:.2}s", elapsed);
    let complete_text = if test.is_complete() {
        "✓ Complete"
    } else {
        "✗ Incomplete"
    };

    let wpm_widget = Paragraph::new(wpm_text)
        .block(Block::default().borders(Borders::ALL).title("WPM"))
        .style(Style::default().fg(Color::Green));
