fn get_config_dir() -> PathBuf {
    if let Ok(xdg_config) = std::env::var("XDG_CONFIG_HOME") {
        PathBuf::from(xdg_config).join("thokr")
    } else if let Ok(home) = std::env::var("HOME") {
        PathBuf::from(home).join(".config").join("thokr")
    } else {
        PathBuf::from(".config/thokr")
    }
}

fn log_results(test: &TypingTest) -> Result<(), Box<dyn Error>> {
    let config_dir = get_config_dir();
    fs::create_dir_all(&config_dir)?;

    let log_file = config_dir.join("log.csv");
    let wpm = test.get_wpm();
    let accuracy = test.get_accuracy();
    let elapsed = if let (Some(start), Some(end)) = (test.start_time, test.end_time) {
        (end - start).as_secs_f64()
    } else {
        0.0
    };

    // Simple timestamp generation using system time
    let timestamp = get_timestamp();
    let log_entry = format!(
        "{},{:.2},{:.2},{:.2}\n",
        timestamp, wpm, accuracy, elapsed
    );

    // Append to log file
    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_file)?;
    file.write_all(log_entry.as_bytes())?;

    Ok(())
}

fn get_timestamp() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};

    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = duration.as_secs();

    // Very basic timestamp - just use unix timestamp for now
    // In a real implementation, we'd parse the time properly
    format!("{}", secs)
}

fn is_tty(fd: i32) -> bool {
    unsafe {
        libc::isatty(fd) == 1
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    // Check if stdin is a TTY
    if !is_tty(0) {  // 0 is STDIN_FILENO
        eprintln!("error: stdin must be a tty\n");
        eprintln!("USAGE:");
        eprintln!("    thokr [OPTIONS]\n");
        eprintln!("For more information try --help");
        std::process::exit(1);
    }

    let args = Args::parse();
    let prompt = generate_prompt(&args);
    let test = TypingTest::new(prompt, args.number_of_secs);

    let mut terminal = setup_terminal()?;
    run_typing_test(&mut terminal, test)?;

    Ok(())
}
