        let sentence_length = 5 + ((seed as usize) % 6);
        let mut sentence_words = Vec::new();

        for j in 0..sentence_length {
            let idx = ((seed.wrapping_add(j as u32) as usize) ^ (j * 7919)) % words.len();
            sentence_words.push(words[idx].to_string());
        }

        if let Some(first) = sentence_words.first_mut() {
