        generate_sentences(sentences)
    } else {
        let word_count = args.number_of_words;
        let word_list = get_word_list(&args.supported_language);

        // Use a simple deterministic pseudo-random selection
        let seed = (Instant::now().elapsed().as_nanos() as u32) ^ 0xDEADBEEF;

        let mut result = Vec::new();
        for i in 0..word_count {
            let idx = ((seed.wrapping_add(i as u32) as usize) ^ (i * 7919)) % word_list.len();
            result.push(word_list[idx].to_string());
