    let secs = duration.as_secs();

    format!("{}", secs)
}

fn run_typing_test(args: Args) -> io::Result<()> {
    // Enter raw mode
    let original_termios = enable_raw_mode()?;

    // Hide cursor and clear screen
    print!("\x1B[?25l\x1B[2J\x1B[H");
    io::stdout().flush()?;

    let prompt_words = generate_prompt(&args);
    let target = prompt_words.join(" ");

    let mut user_input = String::new();
    let mut start_time: Option<Instant> = None;
    let mut end_time: Option<Instant> = None;

    loop {
        // Check time limit
        if let (Some(start), Some(limit)) = (start_time, args.number_of_secs) {
            if start.elapsed().as_secs() >= limit {
                end_time = Some(Instant::now());
                break;
            }
        }

        // Draw UI
        draw_ui(&target, &user_input, start_time)?;

        // Read input with timeout
        let mut buf = [0u8; 1];
        let mut stdin = io::stdin();

        if read_with_timeout(&mut stdin, &mut buf, 100) == Some(1) {
            let c = buf[0] as char;

            if start_time.is_none() {
                start_time = Some(Instant::now());
            }

            match c {
                '\x1B' => {
                    // Escape key
                    end_time = Some(Instant::now());
                    break;
                }
                '\x08' | '\x7F' => {
                    // Backspace
                    user_input.pop();
                }
                c if !c.is_control() => {
                    if user_input.len() < target.len() {
                        user_input.push(c);
                    }

                    if user_input == target {
                        end_time = Some(Instant::now());
                        break;
                    }
                }
                _ => {}
            }
        }
    }

    // Calculate stats
    let elapsed = if let (Some(start), Some(end)) = (start_time, end_time) {
        (end - start).as_secs_f64()
    } else {
        0.0
    };

    let mut correct = 0;
    for (a, b) in user_input.chars().zip(target.chars()) {
        if a == b {
            correct += 1;
        }
    }
    let accuracy = if target.is_empty() {
        100.0
    } else {
        (correct as f64 / target.len() as f64) * 100.0
    };

    let word_count = user_input.split_whitespace().count() as f64;
    let wpm = if elapsed > 0.0 {
        (word_count / elapsed) * 60.0
    } else {
        0.0
    };

    // Draw results
    draw_results(&user_input, &target, wpm, accuracy, elapsed)?;

    // Show results for a moment
    std::thread::sleep(Duration::from_secs(2));

    // Restore terminal
    print!("\x1B[2J\x1B[H\x1B[?25h");
    io::stdout().flush()?;
    disable_raw_mode(original_termios)?;

    // Log results
    let _ = log_results(wpm, accuracy, elapsed);

    Ok(())
}

fn read_with_timeout(_stdin: &mut io::Stdin, buf: &mut [u8], millis: u64) -> Option<usize> {
    // Simple non-blocking read using file descriptor operations
    unsafe {
        let fd = 0i32;  // stdin fd
        let mut set: libc_fd_set = std::mem::zeroed();

        // Manually set the bit for fd 0
        set.fds_bits[0] = 1;

        let mut tv = libc_timeval {
            tv_sec: (millis / 1000) as i64,
            tv_usec: ((millis % 1000) * 1000) as i64,
        };

        let ret = select(fd + 1, &mut set, std::ptr::null_mut(), std::ptr::null_mut(), &mut tv);
        if ret > 0 {
            // Try to read
            match io::stdin().read(buf) {
                Ok(n) => Some(n),
                Err(_) => None,
            }
        } else {
            None
        }
    }
}

fn draw_ui(target: &str, user_input: &str, start_time: Option<Instant>) -> io::Result<()> {
    // Clear screen and move to home
    print!("\x1B[2J\x1B[H");

    // Display prompt
    println!("\x1B[1m=== Typing Test ===\x1B[0m\n");
    println!("Prompt:\n{}\n", target);

    // Display user input with colors
    print!("Your input:\n");
    for (i, c) in target.chars().enumerate() {
        if let Some(uc) = user_input.chars().nth(i) {
            if uc == c {
                print!("\x1B[32m{}\x1B[0m", uc);  // Green for correct
            } else {
                print!("\x1B[31m{}\x1B[0m", uc);  // Red for incorrect
            }
        }
    }

    // Show remaining characters in gray
    if user_input.len() < target.len() {
        print!("\x1B[90m{}\x1B[0m", &target[user_input.len()..]);
    }

    println!("\n");

    // Display timer
    if let Some(start) = start_time {
        println!("Elapsed: {:.1}s\n", start.elapsed().as_secs_f64());
    } else {
        println!("Not started\n");
    }

    println!("Press Esc or arrow keys to quit, Backspace to delete");

    io::stdout().flush()
}

fn draw_results(user_input: &str, target: &str, wpm: f64, accuracy: f64, elapsed: f64) -> io::Result<()> {
    print!("\x1B[2J\x1B[H");

    println!("\x1B[1m=== Results ===\x1B[0m\n");

    let complete = user_input == target;
    println!("Status: {}\n", if complete { "✓ Complete" } else { "✗ Incomplete" });
    println!("WPM: {:.2}", wpm);
    println!("Accuracy: {:.2}%", accuracy);
    println!("Time: {:.2}s\n", elapsed);

    io::stdout().flush()
}

fn main() {
    match parse_args() {
        Ok(args) => {
            if args.show_help {
                print_help("executable");
                process::exit(0);
            }
            if args.show_version {
                println!("thokr 0.4.1");
                process::exit(0);
            }

            // Check if stdin is a TTY only if we're going to run the TUI
            if !is_tty(0) {
                eprintln!("error: stdin must be a tty\n");
                eprintln!("USAGE:");
                eprintln!("    thokr [OPTIONS]\n");
                eprintln!("For more information try --help");
                process::exit(1);
            }

            // Run the typing test
            if let Err(e) = run_typing_test(args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("error: {}\n", e);
            eprintln!("USAGE:");
            eprintln!("    thokr [OPTIONS]\n");
            eprintln!("For more information try --help");
            process::exit(1);
        }
    }
}
